// Gantt Chart — Time Series, route: jsx
// Source: original:gaps/gantt
//
// Self-contained: every local import is inlined below. Requires only d3, react.
// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

// ---- inlined from Axis ----
type Tick = { value: string; offset: number };

function AxisBottom({
  ticks,
  height,
  width
}: {
  ticks: Tick[];
  height: number;
  width: number;
}) {
  return (
    <g className="axis" transform={`translate(0,${height})`}>
      <line x1={0} x2={width} y1={0} y2={0} />
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(${offset},0)`}>
          <line y1={0} y2={5} />
          <text y={18} textAnchor="middle">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

function AxisLeft({ ticks, width }: { ticks: Tick[]; width: number }) {
  return (
    <g className="axis">
      {ticks.map(({ value, offset }) => (
        <g key={value} transform={`translate(0,${offset})`}>
          <line className="grid" x1={0} x2={width} y1={0} y2={0} />
          <text x={-10} dy="0.32em" textAnchor="end">
            {value}
          </text>
        </g>
      ))}
    </g>
  );
}

// ---- inlined from gantt ----
// A product launch plan: ten tasks in three lanes over the first half of 2026.
// Spans overlap within and across lanes — the overlap is what the chart shows.
// Fixed Date constructions keep every render identical.
const launchPlan: { task: string; lane: string; start: Date; end: Date }[] = [
  { task: 'User research', lane: 'Design', start: new Date(2026, 0, 5), end: new Date(2026, 0, 30) },
  { task: 'Wireframes', lane: 'Design', start: new Date(2026, 0, 20), end: new Date(2026, 1, 20) },
  { task: 'Visual design', lane: 'Design', start: new Date(2026, 1, 10), end: new Date(2026, 2, 13) },
  { task: 'API contract', lane: 'Engineering', start: new Date(2026, 1, 2), end: new Date(2026, 1, 27) },
  { task: 'Backend build', lane: 'Engineering', start: new Date(2026, 1, 16), end: new Date(2026, 3, 24) },
  { task: 'Frontend build', lane: 'Engineering', start: new Date(2026, 2, 2), end: new Date(2026, 4, 8) },
  { task: 'Integration tests', lane: 'Engineering', start: new Date(2026, 3, 20), end: new Date(2026, 4, 22) },
  { task: 'Marketing site', lane: 'Launch', start: new Date(2026, 3, 27), end: new Date(2026, 4, 29) },
  { task: 'Beta program', lane: 'Launch', start: new Date(2026, 4, 4), end: new Date(2026, 5, 5) },
  { task: 'Launch prep', lane: 'Launch', start: new Date(2026, 4, 25), end: new Date(2026, 5, 19) }
];

const MARGIN = { top: 6, right: 12, bottom: 34, left: 116 };
const ROW = 22;
const BAR = 14;
const LANE_ROW = 22;
const LANE_GAP = 8;

const formatMonth = d3.timeFormat('%b');

/** Tasks in presentation order, grouped visually by `lane`; start and end are dates. */
export type Data = { task: string; lane: string; start: Date; end: Date }[];

export default function GanttChart({ data = launchPlan, width }: { data?: Data; width: number }) {
  const innerWidth = Math.max(0, width - MARGIN.left - MARGIN.right);

  const x = useMemo(
    () =>
      d3
        .scaleTime()
        .domain([
          d3.min(data, (d) => d.start) ?? new Date(2026, 0, 1),
          d3.max(data, (d) => d.end) ?? new Date(2026, 5, 30)
        ])
        .range([0, innerWidth]),
    [data, innerWidth]
  );

  const lanes = useMemo(() => [...new Set(data.map((d) => d.lane))], [data]);

  const color = useMemo(
    () => d3.scaleOrdinal<string, string>().domain(lanes).range(d3.schemeObservable10),
    [lanes]
  );

  // Walk the lanes in first-appearance order: a header row per lane, a row per task,
  // and a separator line between consecutive lane groups.
  const { rows, headers, separators, innerHeight } = useMemo(() => {
    const grouped = d3.group(data, (d) => d.lane);
    const rows: { task: string; lane: string; start: Date; end: Date; y: number }[] = [];
    const headers: { lane: string; y: number }[] = [];
    const separators: number[] = [];
    let cursor = 0;
    for (const [lane, tasks] of grouped) {
      if (cursor > 0) {
        cursor += LANE_GAP;
        separators.push(cursor);
        cursor += LANE_GAP;
      }
      headers.push({ lane, y: cursor });
      cursor += LANE_ROW;
      for (const t of tasks) {
        rows.push({ ...t, y: cursor });
        cursor += ROW;
      }
    }
    return { rows, headers, separators, innerHeight: cursor };
  }, [data]);

  const ticks: Tick[] = useMemo(
    () =>
      x.ticks(innerWidth < 480 ? 4 : 6).map((v) => ({ value: formatMonth(v), offset: x(v) })),
    [x, innerWidth]
  );

  const height = innerHeight + MARGIN.top + MARGIN.bottom;

  if (width === 0) return null;

  return (
    <svg
      viewBox={`0 0 ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Gantt chart of a ten-task product launch plan in three lanes, with overlapping task bars on a shared time axis from January to June 2026"
    >
      <g transform={`translate(${MARGIN.left},${MARGIN.top})`}>
        <g className="axis">
          {ticks.map((t) => (
            <line key={t.value} className="grid" x1={t.offset} x2={t.offset} y1={0} y2={innerHeight} />
          ))}
        </g>
        {separators.map((sy) => (
          <line key={sy} x1={-MARGIN.left + 6} x2={innerWidth} y1={sy} y2={sy} stroke="var(--line)" />
        ))}
        {headers.map((h) => (
          <text
            key={h.lane}
            x={-MARGIN.left + 6}
            y={h.y + LANE_ROW / 2}
            dy="0.32em"
            fontSize={11}
            fontWeight={600}
            fill={color(h.lane)}
          >
            {h.lane}
          </text>
        ))}
        {rows.map((d) => {
          const middle = d.y + ROW / 2;
          return (
            <g key={d.task}>
              <text x={-8} y={middle} dy="0.32em" textAnchor="end" fontSize={10} fill="var(--text)">
                {d.task}
              </text>
              <rect
                x={x(d.start)}
                y={middle - BAR / 2}
                width={Math.max(1, x(d.end) - x(d.start))}
                height={BAR}
                rx={2}
                fill={color(d.lane)}
              />
            </g>
          );
        })}
        <AxisBottom ticks={ticks} height={innerHeight} width={innerWidth} />
      </g>
    </svg>
  );
}
